-- EngineerOS Genel7 Vocabulary Database
CREATE TABLE vocabulary_terms (
    id VARCHAR(100) PRIMARY KEY,
    term VARCHAR(500) NOT NULL,
    normalized_term VARCHAR(500),
    turkish_meaning TEXT,
    cefr_level VARCHAR(10),
    domain VARCHAR(100),
    content_domain VARCHAR(100),
    life_context VARCHAR(100),
    register VARCHAR(50),
    primary_use_case VARCHAR(100),
    category VARCHAR(200),
    term_type VARCHAR(50),
    part_of_speech VARCHAR(50),
    word_count INTEGER,
    definition TEXT,
    example_sentence TEXT,
    turkish_example TEXT,
    related_terms TEXT,
    common_mistakes TEXT,
    grammar_fits TEXT,
    skill_use TEXT,
    tags TEXT,
    source TEXT,
    confidence DECIMAL(3,2),
    status VARCHAR(50),
    import_tier VARCHAR(100),
    is_core BOOLEAN,
    is_technical BOOLEAN,
    is_professional_phrase BOOLEAN,
    is_contractual BOOLEAN,
    is_daily_site_english BOOLEAN,
    is_life_wide_english BOOLEAN,
    review_reason TEXT,
    variant_of VARCHAR(200),
    grammar_domain_alias VARCHAR(100),
    qc_repair_notes TEXT
);
