INSERT INTO vocabulary_terms VALUES ('vocab_education_learning_a1_0001', 'news', 'news', 'haber', 'A1', 'general-english', 'general', 'technical-learning', 'neutral', 'daily-conversation', 'BBC / articles', 'single_word', 'noun', 1, 'An education and learning term meaning haber, used for self-study, courses or technical learning.', 'The news appeared in today’s English lesson.', 'Haber bugünkü İngilizce dersinde geçti.', 'work, site, communication, report, vocabulary', 'Do not memorize only the Turkish meaning; learn one natural sentence with the word. For “news”, learn one real sentence instead of only the Turkish meaning.', 'simple present, questions, technical reporting, relative clauses', 'reading, writing, vocabulary', 'a1, bbc-articles, education, education-learning, engineeros, general-site, single_word, transferred-to-general', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'extended_vocabulary', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'general', 'domain_mapping: domain mapped to general | Final polish: mechanical template removed; English/Turkish naturalness repaired | domain_merged_to_general', 1);
INSERT INTO vocabulary_terms VALUES ('vocab_education_learning_a1_0002', 'newspaper', 'newspaper', 'gazete', 'A1', 'general-english', 'general', 'technical-learning', 'neutral', 'daily-conversation', 'BBC / articles', 'single_word', 'noun', 1, 'An education and learning term meaning gazete, used for self-study, courses or technical learning.', 'Please write the newspaper in your vocabulary notebook.', 'Lütfen gazete kelimesini kelime defterine yaz.', 'work, site, communication, report, vocabulary', 'Use this term in learning, course or explanation contexts, not only in isolated word lists. For “newspaper”, learn one real sentence instead of only the Turkish meaning.', 'simple present, questions, technical reporting, relative clauses', 'reading, writing, vocabulary', 'a1, bbc-articles, education, education-learning, engineeros, general-site, single_word, transferred-to-general', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'extended_vocabulary', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'general', 'domain_mapping: domain mapped to general | Final polish: mechanical template removed; English/Turkish naturalness repaired | domain_merged_to_general', 1);
INSERT INTO vocabulary_terms VALUES ('vocab_education_learning_a1_0003', 'online', 'online', 'çevrim içi', 'A1', 'general-english', 'general', 'technical-learning', 'neutral', 'daily-conversation', 'IT & data', 'single_word', 'adverb', 1, 'An adverb meaning “çevrim içi”, used to describe how or when an action is done.', 'We completed the safety training online.', 'İş güvenliği eğitimini çevrim içi tamamladık.', 'work, site, communication, report, vocabulary', 'Do not use “the online” as a noun; use it to describe how or when an action happens.', 'simple present, prepositions, daily conversation', 'reading, writing, vocabulary', 'a1, education, education-learning, engineeros, general-site, it-data, single_word, transferred-to-general', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'extended_vocabulary', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'general', 'domain_mapping: domain mapped to general | domain_merged_to_general', 1);
