INSERT INTO vocabulary_terms VALUES ('vocab_finance_admin_a1_0001', 'card', 'card', 'kart', 'A1', 'EngGen', 'workplace', 'bank', 'formal', 'work-report', 'access & security', 'finance_admin_term', 'noun', 1, 'A finance/admin term meaning kart, used for payments, salary, banking, tax, visa or document communication.', 'The accountant reviewed the card before month-end closing.', 'Muhasebeci ay kapanışından önce kart gözden geçirdi.', 'work, site, communication, report, vocabulary', 'Do not say ''send money by bank'' in formal English; use make a bank transfer when relevant. For “card”, include the amount, date or document reference when needed.', 'questions, simple present, finance-admin wording, modal obligation, prepositions', 'reading, writing, speaking, vocabulary', 'a1, access-security, engineeros, finance-admin, finance_admin_term, general-site, EngGen', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'finance_admin_english', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'EngGen', 'domain_mapping: domain mapped to general | Final polish: mechanical template removed; English/Turkish naturalness repaired | merged_to_EngGen', 1);
INSERT INTO vocabulary_terms VALUES ('vocab_travel_a1_0001', 'address', 'address', 'adres / adreslemek', 'A1', 'general-english', 'general', 'problem-solving', 'neutral', 'daily-conversation', 'communication', 'single_word', 'noun', 1, 'A travel English term meaning adres / adreslemek, used for airport, hotel, taxi, restaurant or relocation situations.', 'I need to confirm the address before I arrive.', 'Gelmeden önce adres / adreslemek konusunu teyit etmem gerekiyor.', 'work, site, communication, report, vocabulary', 'Do not use this as a technical site term; it belongs to travel or daily-life communication. For “address”, use a short direct question in travel situations.', 'questions, simple present, travel conversation, prepositions, modal advice', 'listening, speaking, vocabulary', 'a1, communication, engineeros, general-site, single_word, travel, transferred-to-general', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'travel_english', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'general', 'domain_mapping: domain mapped to general | domain_merged_to_general', 1);
