INSERT INTO vocabulary_terms VALUES ('vocab_finance_admin_a1_0002', 'bank', 'bank', 'banka', 'A1', 'EngGen', 'workplace', 'bank', 'formal', 'work-report', 'daily life', 'finance_admin_term', 'noun', 1, 'A finance/admin term meaning banka, used for payments, salary, banking, tax, visa or document communication.', 'The bank transfer may take two working days.', 'Banka transferi iki iş günü sürebilir.', 'work, site, communication, report, vocabulary', 'Do not say ''send money by bank'' in formal English; use make a bank transfer when relevant. For “bank”, include the amount, date or document reference when needed.', 'questions, simple present, finance-admin wording, modal obligation, prepositions', 'reading, writing, speaking, vocabulary', 'a1, daily-life, engineeros, finance-admin, finance_admin_term, general-site, EngGen', 'Clean curated single-word rebuild + Final QC life-wide normalization', 0.92, 'approved', 'finance_admin_english', FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, NULL, NULL, 'EngGen', 'domain_mapping: domain mapped to general | merged_to_EngGen', 1);
